// Code generated by packages/kit-compose/src/organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
/**
 * The simple stories (model stories@1): the heading, a description and the stories (posts) as a list, each with
 * a cover picture, the title (a link when the story has an address) and a line. Axes: layout (grid: cards in
 * columns, compact: small covers beside the copy on a card surface), cols (2, 3 columns).
 */
import { type ReactNode } from "react";
import { Block, Container, Link, List, ListItem, Stack, Text, Title } from "../compose";
import { MediaFrame } from "../components/media-frame";
import { cn, urlOf } from "../utils";
import type { SimpleStory } from "./stories-simple.types";

export type StoriesSimpleProps = {
  id: string;
  title: string;
  description?: string;
  stories: SimpleStory[];
  level?: 1 | 2 | 3;
  padding?: "compact" | "standard" | "spacious";
  align?: "start" | "center" | "end";
  layout?: "grid" | "compact";
  cols?: "2" | "3";
  landmarkLabel?: string;
};

export function StoriesSimple({
  id,
  title,
  description = "",
  stories,
  level = 2,
  padding = "standard",
  align = "center",
  layout = "grid",
  cols = "3",
  landmarkLabel,
}: StoriesSimpleProps) {
  const titleId = id + "-title";
  const column =
    (align as string) === "center" ? "center"
    : (align as string) === "end" ? "end"
    : "start";
  const textAlign =
    (align as string) === "center" ? "text-center"
    : (align as string) === "end" ? "text-end"
    : "text-start";
  const itemsAlign =
    (align as string) === "center" ? "items-center"
    : (align as string) === "end" ? "items-end"
    : "items-start";
  const selfAlign =
    (align as string) === "center" ? "self-center"
    : (align as string) === "end" ? "self-end"
    : "";
  const grid = ((cols as string) === "2") ? "md:grid-cols-2" : "md:grid-cols-3";
  const item =
    (layout as string) === "compact" ? "flex flex-row items-center gap-4 rounded bg-card p-4 text-card-foreground border border-border"
    : "flex flex-col gap-4";
  const coverRatio =
    (layout as string) === "compact" ? "1/1"
    : (cols as string) === "2" ? "16/9"
    : "4/3";
  const cover = ((layout as string) === "compact") ? "size-16 shrink-0" : "";
  return (
    <Block
      tag="section"
      className={
        (padding as string) === "compact" ? "py-8 lg:py-16"
        : (padding as string) === "spacious" ? "py-24 lg:py-40"
        : "py-16 lg:py-32"
      }
      aria-labelledby={(landmarkLabel ? undefined : titleId)}
      aria-label={landmarkLabel}
      data-slot="stories-simple"
    >
      <Container className="mx-auto w-full max-w-6xl px-4">
        <Stack gap="12" align="stretch">
          <Stack gap="4" align={column} className={cn("max-w-2xl", selfAlign)}>
            <Title as={level} size="3xl" weight="bold" className={cn("tracking-tight", textAlign)} id={titleId}>
              {title}
            </Title>
            {description ? (
              <Text size="base" className={cn("text-muted-foreground", textAlign)}>
                {description}
              </Text>
            ) : null}
          </Stack>
          <List tag="ul" className={cn("m-0 w-full list-none p-0", cn("grid grid-cols-1 gap-8", grid))}>
            {(stories ?? []).map((s) => (
              <ListItem key={s.id} className={item} data-slot="story">
                <MediaFrame alt={s.title} src={s.image} ratio={coverRatio} className={cover} />
                <Stack gap="2" align="start">
                  {s.href ? (
                    <Link href={urlOf(s.href)} variant="block">
                      <Title as={(level + 1)} size="lg" weight="semibold" className="text-start">
                        {s.title}
                      </Title>
                    </Link>
                  ) : (
                    <Title as={(level + 1)} size="lg" weight="semibold" className="text-start">
                      {s.title}
                    </Title>
                  )}
                  {s.description ? (
                    <Text size="sm" className={cn("text-muted-foreground", "text-start")}>
                      {s.description}
                    </Text>
                  ) : null}
                </Stack>
              </ListItem>
            ))}
          </List>
        </Stack>
      </Container>
    </Block>
  );
}

